drop policy if exists certificates_member_all on public.certificates;
drop policy if exists certificate_attachments_member_all on public.certificate_attachments;
create policy certificates_member_select on public.certificates for select to authenticated using(exists(select 1 from public.church_members cm where cm.church_id=certificates.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary','staff')));
create policy certificates_staff_insert on public.certificates for insert to authenticated with check(exists(select 1 from public.church_members cm where cm.church_id=certificates.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary','staff')));
create policy certificates_staff_update on public.certificates for update to authenticated using(exists(select 1 from public.church_members cm where cm.church_id=certificates.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary','staff'))) with check(exists(select 1 from public.church_members cm where cm.church_id=certificates.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary','staff')));
create policy certificate_attachments_staff_select on public.certificate_attachments for select to authenticated using(exists(select 1 from public.church_members cm where cm.church_id=certificate_attachments.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary')));
create policy certificate_attachments_staff_insert on public.certificate_attachments for insert to authenticated with check(exists(select 1 from public.church_members cm where cm.church_id=certificate_attachments.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary')));
create policy certificate_attachments_staff_update on public.certificate_attachments for update to authenticated using(exists(select 1 from public.church_members cm where cm.church_id=certificate_attachments.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary'))) with check(exists(select 1 from public.church_members cm where cm.church_id=certificate_attachments.church_id and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary')));
drop policy if exists church_docs_member_read on storage.objects;
drop policy if exists church_docs_member_upload on storage.objects;
drop policy if exists church_docs_member_update on storage.objects;
create policy church_docs_staff_read on storage.objects for select to authenticated using(bucket_id='church-private-documents' and exists(select 1 from public.church_members cm where cm.church_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary')));
create policy church_docs_staff_upload on storage.objects for insert to authenticated with check(bucket_id='church-private-documents' and exists(select 1 from public.church_members cm where cm.church_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary')));
create policy church_docs_staff_update on storage.objects for update to authenticated using(bucket_id='church-private-documents' and exists(select 1 from public.church_members cm where cm.church_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary'))) with check(bucket_id='church-private-documents' and exists(select 1 from public.church_members cm where cm.church_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin','pastor','secretary')));
